INSERT OR IGNORE INTO content_sections(event_id,key,label,value) SELECT id,'plans_hosted_intro','Plans — confirmed plans introduction','Organizer-confirmed plans appear here as details are finalized.' FROM events WHERE slug='trina-60-2029';
INSERT OR IGNORE INTO content_sections(event_id,key,label,value) SELECT id,'plans_ideas_intro','Plans — guest ideas introduction','These are ideas from Trina''s planning notes—not a fixed schedule. Guests can choose what fits them.' FROM events WHERE slug='trina-60-2029';
INSERT OR IGNORE INTO content_sections(event_id,key,label,value) SELECT id,'explore_culture_intro','Explore — Black culture and history','Start with the experiences that make this trip special.' FROM events WHERE slug='trina-60-2029';
INSERT OR IGNORE INTO content_sections(event_id,key,label,value) SELECT id,'explore_events_note','Explore — events note','Event dates and availability for August 2029 will need to be confirmed later.' FROM events WHERE slug='trina-60-2029';
INSERT OR IGNORE INTO content_sections(event_id,key,label,value) SELECT id,'explore_footer_note','Explore — additional notes','Circuit Avenue for browsing and evening activity, The Ritz Cafe or The Loft for live music and relaxed crowds, and Eleven for themed nights. These are options, not required plans.' FROM events WHERE slug='trina-60-2029';
INSERT OR IGNORE INTO content_sections(event_id,key,label,value) SELECT id,'before_reservation_intro','Before You Go — reservation timeline','Decide how many days you want to stay, start saving early, and reserve the most important parts of the trip first.' FROM events WHERE slug='trina-60-2029';
INSERT OR IGNORE INTO content_sections(event_id,key,label,value) SELECT id,'before_ferry_note','Before You Go — luggage and ferry-day note','Trina''s notes list Dockside Inn in Oak Bluffs for luggage storage at $10 per bag for the day, across from Sandbar.' FROM events WHERE slug='trina-60-2029';
INSERT OR IGNORE INTO content_sections(event_id,key,label,value) SELECT id,'community_story','Community — planning and memories','Before the trip, this is a place to coordinate. During the trip, it is a place to share. After the trip, it becomes a digital keepsake.' FROM events WHERE slug='trina-60-2029';
INSERT OR IGNORE INTO content_sections(event_id,key,label,value) SELECT id,'community_keepsake_intro','Community — keepsakes introduction','Add photos and messages so the memories remain together after the trip.' FROM events WHERE slug='trina-60-2029';
INSERT OR IGNORE INTO content_sections(event_id,key,label,value) SELECT id,'about_basics','About MV — island overview','Martha''s Vineyard is an island about seven miles off the Massachusetts coast, with six towns, beaches, harbors, lighthouses, bike paths, galleries, restaurants, historic villages, and protected coastal land.' FROM events WHERE slug='trina-60-2029';
INSERT OR IGNORE INTO content_sections(event_id,key,label,value) SELECT id,'about_black_legacy','About MV — Black American legacy','Oak Bluffs became a place where Black families could vacation, own homes, build businesses, worship, socialize, and create community when segregation sharply limited where Black Americans were welcomed elsewhere.' FROM events WHERE slug='trina-60-2029';
INSERT OR IGNORE INTO content_sections(event_id,key,label,value) SELECT id,'about_trip_meaning','About MV — why this trip matters','For Trina''s milestone trip, this combination matters: beauty, history, Black culture, relaxation, fun, and time together.' FROM events WHERE slug='trina-60-2029';
